=== tools/RunTests.java
     1	import java.io.File;
     2	import java.io.IOException;
     3	import java.nio.file.Files;
     4	import java.nio.file.Path;
     5	import java.util.ArrayList;
     6	import java.util.Comparator;
     7	import java.util.List;
     8	import java.util.stream.Stream;
     9	import javax.tools.JavaCompiler;
    10	import javax.tools.ToolProvider;
    11	
    12	/**
    13	 * Builds and tests the project without Maven or Gradle: {@code java tools/RunTests.java}.
    14	 *
    15	 * <p>Compiles every source under {@code src/} into {@code build/classes} and runs all JUnit 5 tests found there
    16	 * with the console launcher in {@code lib/}. With a directory argument, for example {@code .hidden}, it also
    17	 * compiles that directory against the project and runs only the tests in it.
    18	 */
    19	public class RunTests {
    20	    private static final Path JUNIT = Path.of("lib", "junit-platform-console-standalone.jar");
    21	    private static final Path PROJECT_CLASSES = Path.of("build", "classes");
    22	    private static final Path EXTRA_CLASSES = Path.of("build", "extra-classes");
    23	
    24	    public static void main(String[] args) throws IOException, InterruptedException {
    25	        compileOrExit(Path.of("src"), PROJECT_CLASSES, JUNIT.toString());
    26	        Path testClasses = PROJECT_CLASSES;
    27	        if (args.length > 0) {
    28	            compileOrExit(Path.of(args[0]), EXTRA_CLASSES, classPath(PROJECT_CLASSES, JUNIT));
    29	            testClasses = EXTRA_CLASSES;
    30	        }
    31	        System.exit(runJUnit(testClasses));
    32	    }
    33	
    34	    private static void compileOrExit(Path sources, Path output, String classPath) throws IOException {
    35	        deleteRecursively(output);
    36	        Files.createDirectories(output);
    37	        List<String> arguments = new ArrayList<>(List.of("-d", output.toString(), "-cp", classPath, "-Xlint:all"));
    38	        arguments.addAll(javaFiles(sources));
    39	        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    40	        int status = compiler.run(null, null, null, arguments.toArray(String[]::new));
    41	        if (status != 0) {
    42	            System.err.println("Compilation of " + sources + " failed.");
    43	            System.exit(status);
    44	        }
    45	    }
    46	
    47	    private static int runJUnit(Path testClasses) throws IOException, InterruptedException {
    48	        String java = ProcessHandle.current().info().command().orElse("java");
    49	        Process launcher = new ProcessBuilder(
    50	                        java, "-jar", JUNIT.toString(), "execute",
    51	                        "--class-path", classPath(testClasses, PROJECT_CLASSES),
    52	                        "--scan-class-path", testClasses.toString(),
    53	                        "--disable-banner", "--disable-ansi-colors", "--details=tree")
    54	                .inheritIO()
    55	                .start();
    56	        return launcher.waitFor();
    57	    }
    58	
    59	    private static String classPath(Path... entries) {
    60	        return String.join(File.pathSeparator, Stream.of(entries).map(Path::toString).toList());
    61	    }
    62	
    63	    private static List<String> javaFiles(Path root) throws IOException {
    64	        try (Stream<Path> paths = Files.walk(root)) {
    65	            return paths.filter(path -> path.toString().endsWith(".java")).map(Path::toString).sorted().toList();
    66	        }
    67	    }
    68	
    69	    private static void deleteRecursively(Path root) throws IOException {
    70	        if (!Files.exists(root)) {
    71	            return;
    72	        }
    73	        try (Stream<Path> paths = Files.walk(root)) {
    74	            for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) {
    75	                Files.delete(path);
    76	            }
    77	        }
    78	    }
    79	}
