package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>The file is rejected as a whole if anything in it is wrong: the file is missing or unreadable, a key is
 * unknown (usually a typo), a required key is absent, or a value cannot be parsed or is out of range. Every
 * problem is reported in one {@link ConfigException}. An optional key that is absent takes its default; a key
 * that is present is never silently replaced by a default.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();
        checkForUnknownKeys(properties, problems);

        URI upstream = uri(properties, "upstream.url", problems);
        String apiToken = required(properties, "api.token", problems);
        int workerThreads = intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, "request.timeout", DEFAULT_REQUEST_TIMEOUT, problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", false, problems);

        if (!problems.isEmpty()) {
            throw new ConfigException(describe(file, problems));
        }
        return new ServiceConfig(
                upstream,
                apiToken,
                workerThreads,
                queueCapacity,
                retryAttempts,
                requestTimeout,
                metricsEnabled);
    }

    private static Properties read(Path file) {
        if (!Files.isRegularFile(file)) {
            throw new ConfigException("cannot read configuration file " + file
                    + ": the file does not exist (copy config.example.properties to start)");
        }
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("cannot read configuration file " + file + ": " + e.getMessage());
        }
        return properties;
    }

    private static void checkForUnknownKeys(Properties properties, List<String> problems) {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key '" + key + "': check the spelling against config.example.properties");
            }
        }
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private static URI uri(Properties properties, String key, List<String> problems) {
        String raw = required(properties, key, problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            if (uri.isAbsolute() && ("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))
                    && uri.getHost() != null) {
                return uri;
            }
        } catch (Exception e) {
            // reported below
        }
        problems.add(key + ": '" + raw + "' is not an absolute http or https URL");
        return null;
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum,
            List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String value = raw.trim();
        try {
            int number = Integer.parseInt(value);
            if (number >= minimum) {
                return number;
            }
            problems.add(key + ": " + number + " is too small, it must be at least " + minimum);
        } catch (NumberFormatException e) {
            problems.add(key + ": '" + value + "' is not a whole number");
        }
        return defaultValue;
    }

    private static Duration duration(Properties properties, String key, Duration defaultValue,
            List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String value = raw.trim();
        Matcher matcher = DURATION.matcher(value);
        if (!matcher.matches()) {
            problems.add(key + ": '" + value + "' is not a duration, use a whole number followed by ms, s or m"
                    + " (for example 30s)");
            return defaultValue;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(key + ": '" + value + "' is too large");
            return defaultValue;
        }
    }

    private static boolean bool(Properties properties, String key, boolean defaultValue, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String value = raw.trim();
        if (value.equalsIgnoreCase("true")) {
            return true;
        }
        if (value.equalsIgnoreCase("false")) {
            return false;
        }
        problems.add(key + ": '" + value + "' must be true or false");
        return defaultValue;
    }

    private static String describe(Path file, List<String> problems) {
        StringBuilder message = new StringBuilder("invalid configuration in ")
                .append(file)
                .append(" (")
                .append(problems.size())
                .append(problems.size() == 1 ? " problem" : " problems")
                .append("):");
        for (String problem : problems) {
            message.append("\n  - ").append(problem);
        }
        return message.toString();
    }
}

